    1  // A small, dependency-free line chart renderer: draws into a container as SVG
    2  // with axes, gridlines, per-district lines, and a hover/tap readout showing
    3  // the exact month and figure. Kept tiny on purpose — nothing to download,
    4  // a handful of DOM nodes, so it stays fast on phones.
    5  
    6  export type Series = { name: string; color: string; points: { month: string; rent: number }[] };
    7  export type ChartHandle = { destroy(): void };
    8  
    9  const NS = 'http://www.w3.org/2000/svg';
   10  
   11  function svgEl(tag: string, attrs: Record<string, string | number>): SVGElement {
   12    const el = document.createElementNS(NS, tag);
   13    for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, String(v));
   14    return el;
   15  }
   16  
   17  function niceStep(raw: number): number {
   18    const pow = Math.pow(10, Math.floor(Math.log10(Math.max(raw, 1e-9))));
   19    for (const m of [1, 2, 2.5, 5, 10]) if (m * pow >= raw) return m * pow;
   20    return 10 * pow;
   21  }
   22  
   23  export function renderLineChart(container: HTMLElement, series: Series[], format: (n: number) => string): ChartHandle {
   24    container.textContent = '';
   25    const months = Array.from(new Set(series.flatMap(s => s.points.map(p => p.month)))).sort();
   26    if (months.length === 0 || series.every(s => s.points.length === 0)) {
   27      const p = document.createElement('p');
   28      p.className = 'chart-empty';
   29      p.textContent = 'No data to chart yet — load a CSV from the data tools below.';
   30      container.appendChild(p);
   31      return { destroy() { p.remove(); } };
   32    }
   33    const width = Math.max(280, Math.floor(container.clientWidth) || 320);
   34    const height = Math.max(230, Math.min(430, Math.round(width * 0.62)));
   35    const m = { top: 14, right: 14, bottom: 30, left: 48 };
   36    const iw = Math.max(10, width - m.left - m.right);
   37    const ih = Math.max(10, height - m.top - m.bottom);
   38    const yMax = Math.max(1, ...series.flatMap(s => s.points.map(p => p.rent)));
   39    const step = niceStep(yMax / 5);
   40    const yTop = Math.max(step, Math.ceil(yMax / step) * step);
   41    const x = (i: number) => months.length > 1 ? m.left + (i / (months.length - 1)) * iw : m.left + iw / 2;
   42    const y = (v: number) => m.top + ih - (v / yTop) * ih;
   43    const monthIndex = new Map(months.map((mo, i) => [mo, i] as const));
   44  
   45    const svg = svgEl('svg', { width, height, viewBox: '0 0 ' + width + ' ' + height, class: 'chart-svg' });
   46    svg.setAttribute('role', 'img');
   47    svg.setAttribute('aria-label', 'Line chart of monthly median rent by district');
   48  
   49    // horizontal gridlines + y labels
   50    for (let v = 0; v <= yTop + 1e-9; v += step) {
   51      const yy = y(v);
   52      svg.appendChild(svgEl('line', { x1: m.left, x2: m.left + iw, y1: yy, y2: yy, class: v === 0 ? 'axis' : 'grid' }));
   53      const t = svgEl('text', { x: m.left - 8, y: yy + 4, class: 'tick tick-y', 'text-anchor': 'end' });
   54      t.textContent = format(v);
   55      svg.appendChild(t);
   56    }
   57    // x labels, thinned to what fits
   58    const maxLabels = Math.max(2, Math.floor(iw / 58));
   59    const skip = Math.max(1, Math.ceil(months.length / maxLabels));
   60    const shown: number[] = [];
